import { tags } from "typia";

/**
 * Per-employee time contribution summary for a specific project, showing each employee's total logged minutes and timelog count.
 *
 * Aggregates time tracking data from active (non-deleted) timelogs associated with the specified project. Joins with employee and member records to provide human-readable employee identification alongside quantitative time metrics. Results are sorted by total minutes in descending order to surface highest contributors first.
 * @autobe Generated by AutoBE - https://github.com/wrtnlabs/autobe
 */
export type IHrmPlatformProjectTimeReport = {
  /**
   * UUID identifier of the employee who performed the tracked work.
   *
   * Uniquely identifies the workforce member within their organization. Used to group and aggregate all time entries belonging to this employee for the specified project.
   *
     * @x-autobe-specification Computed field from GROUP BY
     *   hrm_platform_timelogs.hrm_platform_employee_id →
     *   hrm_platform_employees.id. The employee UUID that identifies the
     *   workforce member who performed the logged work. Used as the grouping
     *   key for per-employee aggregation.
   */
  employee_id: string & tags.Format<"uuid">;

  /**
   * Display name of the employee shown in user interface.
   *
   * Retrieved from the employee's linked member profile (hrm_platform_members.display_name). Provides human-readable identification for reporting and dashboard displays.
   *
     * @x-autobe-specification Computed field from JOIN chain:
     *   hrm_platform_timelogs → hrm_platform_employees (via
     *   hrm_platform_employee_id → hrm_platform_employee_id). Then JOIN to
     *   hrm_platform_members via hrm_platform_member_id. Result maps to
     *   hrm_platform_members.display_name. Returns the display name shown in UI
     *   for identification purposes.
   */
  employee_name: string;

  /**
   * Total minutes of tracked work logged by this employee on the specified project.
   *
   * Aggregated from all active (non-deleted) timelog records. Represents cumulative work duration measured in minutes, used for budget utilization calculations and work distribution analysis.
   *
     * @x-autobe-specification Computed via
     *   SUM(hrm_platform_timelogs.duration_minutes) filtered by projectId and
     *   deleted_at IS NULL. Aggregates duration_minutes into a cumulative
     *   integer total for payroll and budget tracking.
   */
  total_minutes: number & tags.Type<"int32">;

  /**
   * Number of individual timelog entries recorded by this employee for the specified project.
   *
   * Counts active (non-deleted) time tracking records. Provides insight into work session frequency and logging patterns for this employee-project combination.
   *
     * @x-autobe-specification Computed via COUNT(*) from hrm_platform_timelogs
     *   filtered by: hrm_platform_timelogs.hrm_platform_project_id = projectId
     *   AND hrm_platform_timelogs.deleted_at IS NULL AND
     *   hrm_platform_timelogs.hrm_platform_employee_id = employee_id. Counts
     *   the number of individual timelog entries for this employee on this
     *   project. Returns 0 when no timelogs exist.
   */
  timelog_count: number & tags.Type<"int32">;
};
